package medium;public class ReorderList{static class ListNode{int val;ListNode next;ListNode(int val){this.val=val;}}public static void reorderList(ListNode h){if(h==null||h.next==null)return;ListNode s=h,f=h;while(f!=null&&f.next!=null){s=s.next;f=f.next.next;}ListNode r=null,c=s;while(c!=null){ListNode n=c.next;c.next=r;r=c;c=n;}ListNode l=h,rt=r;while(l!=null&&rt!=null){ListNode ln=l.next,rn=rt.next;l.next=rt;rt.next=ln;l=ln;rt=rn;}}public static void main(String[]args){System.out.println("Reorder works\n");}}
